mapper.select:
select *
from archive_template

    and template_name LIKE concat('%', #{req.templateName},'%')
    and FIND_IN_SET(#{req.bizType},template_type) 
    and status = #{req.status}
    and create_time  >=  #{req.createTimeFrom}
    and create_time  <=  #{req.createTimeTo}
    and update_time  >=  #{req.updateTimeFrom}
    and update_time  <=  #{req.updateTimeTo}

order by update_time desc
